create table public.support_messages(id uuid primary key, email text not null check(length(email)<=254), message text not null check(length(message) between 3 and 1000), created_at timestamptz not null default now()); create index support_messages_email_time on public.support_messages(email,created_at); alter table public.support_messages enable row level security; revoke all on public.support_messages from anon,authenticated,public; grant select,insert on public.support_messages to service_role;
